-- A statement taken of a person: the day it was taken (the sheet's today), who took it, their
-- due-total then (null when it was n/a) and how many of their claims counted.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    taken_on  DATE           NOT NULL,
    taken_by  VARCHAR(100)   NOT NULL,
    due_total DECIMAL(14, 2),
    claims    INT            NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
CREATE INDEX statement_sheet ON statement (sheet_id, id);

-- Whether a claim is bound by its person's last statement, and the due it was bound to (null when
-- it had none then, so it stays live). The next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
-- A claim's status log: one line per status it has had, oldest first (by id). Each line keeps who
-- made the change, the sheet's today then, and the claim's due as computed at that moment (null
-- when it had none).
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(20)    NOT NULL,
    by_user   VARCHAR(100)   NOT NULL,
    on_date   DATE           NOT NULL,
    due       DECIMAL(14, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, id);
-- A person's holds are dated: each applies from its from-date to its to-date (open-ended when it
-- has none), and a person may have several over time. While a hold covers a claim's date, the
-- person's open claim of that date (one not bound by a statement) counts in no live total. A person
-- on hold before holds were dated keeps a hold from the beginning of time (no from-date).
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A person's grade is dated: each grade applies from its from-date until a later from-date of the
-- person takes over. The first grade a person was given has no from-date: it applies from the
-- beginning of time. A person has at most one grade per from-date (and one with none).
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE,
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, from_date, grade) SELECT id, NULL, grade FROM person;
ALTER TABLE person DROP COLUMN grade;

